/* Pure, deterministic rules. No model may mutate money or profile. */
(function(root){
'use strict';
const CONFIG={initial:10000,rounds:6,rule:'1.0',xpPerEvent:20};
const people=[{id:'ai',name:'星澜',role:'AI 执行助理',code:'AI',color:'#9eabff',file:'01_ai_assistant.png',dimension:'沟通与复盘',hint:'说说你的理由，选择本身没有标准答案。'}, {id:'risk',name:'凛川',role:'首席风险官',code:'CRO',color:'#76e3cd',file:'02_risk_officer.png',dimension:'风险谨慎程度',hint:'先核对最大损失和退出条件。谨慎不等于永远不行动。'}, {id:'tech',name:'赤霄',role:'首席技术官',code:'CTO',color:'#ffb57b',file:'03_trader.png',dimension:'数据指标参照度',hint:'指标只是线索。先检查样本、费用与样本外表现。'}, {id:'finance',name:'知夏',role:'首席财务官',code:'CFO',color:'#dfc1ff',file:'04_research_mentor.png',dimension:'资金配置意识',hint:'算清投入占比和剩余现金，再决定如何分配。'}];
const families=[
{title:'赤色开盘 · 暴跌之后',type:'波动',concept:'回撤',story:'开盘警报响彻海风港。虚构科技板块突然回落，交易台递来一份短期试验方案。反弹还会来吗？',fact:'这是单轮、无杠杆模拟；执行后立即平仓。没有真实市场数据。',p:40,up:120,down:90},
{title:'完美曲线 · 幻影策略',type:'验证',concept:'样本外验证',story:'一条近乎完美的历史曲线出现在董事会屏幕上。它只展示了最漂亮的一段历史，新的样本还未检验。',fact:'历史曲线是合成叙事，不证明未来收益。下面概率是本游戏的公开规则。',p:45,up:118,down:88},
{title:'无声刺客 · 手续费',type:'成本',concept:'交易成本',story:'高频试验频频报捷，财务台却发现净值几乎没动。每次微小的费用，正在吞噬账面优势。',fact:'净结果 = 返还 − 投入 − 手续费。所有选项都显示完整费用。',p:60,up:105,down:96},
{title:'水晶数据 · 可疑的信号',type:'数据',concept:'未来数据泄漏',story:'一份预测报告总能提前知道收盘价。首席技术官在时间戳里发现了一处异常：模型可能偷看了未来。',fact:'本事件只演示研究流程；模拟概率不代表这份策略可信。',p:35,up:125,down:85},
{title:'午夜来函 · 流动性风暴',type:'配置',concept:'资金占用',story:'两项研究任务同时申请预算。机会不会等人，但事务所也需要保留日常运转的现金。',fact:'本轮投入立即结算；真实的流动性期限没有在本原型模拟。',p:55,up:110,down:93},
{title:'终幕审议 · 你的投资章程',type:'复盘',concept:'概率与结果',story:'城市灯火渐次亮起。董事会希望你制定最后一笔试验预算：这一次，你愿意依据什么拍板？',fact:'单次盈利可能来自运气。解释过程、核对依据，才会增加角色认可。',p:50,up:112,down:92}
];
function rand(seed){let n=seed>>>0;n^=n<<13;n^=n>>>17;n^=n<<5;return (n>>>0)/4294967296;}
function fresh(name,save=false,goal='探索基础',initial=CONFIG.initial,seed=Date.now()>>>0){return {schema:1,id:'run-'+seed,seed,version:0,name:(String(name).trim().slice(0,12)||'玩家').replace(/总+$/,'')||'玩家',save,goal,initial,balance:initial,round:0,phase:'ready',event:null,draft:null,ledger:[],xp:0,evidence:[],corrections:{},profileVersion:1,lessons:[],quiz:[],chats:[],npc:0,prompted:[],resourceFeedback:[],cg:'idle'};}
function eventFor(s){const index=s.round===0?0:((s.seed%5+s.round-1)%5)+1;const f=families[index];const factor=[1,1.2,.8][Math.floor(rand(s.seed+s.round+21)*3)];const amount=Math.floor(1000*factor);const e={...f,id:s.id+'-e'+s.round,version:1,rule:CONFIG.rule,seed:(s.seed+s.round*7919+17)>>>0,p:f.p,amount,fee:Math.ceil(amount/100),report:50,rarity:s.round>=3?'SSR':'SR',source:'Mock 参数组合'};validate(e);return e;}
function validate(e){if(!Number.isInteger(e.p)||e.p<0||e.p>100||!Number.isInteger(e.amount)||e.amount<1||e.amount>5000||!Number.isInteger(e.fee)||e.fee<0||e.up<0||e.up>200||e.down<0||e.down>200)throw Error('事件规则校验失败');return true;}
function draw(s){if(s.phase!=='ready')return s.event;s.event=eventFor(s);s.phase='event';s.version++;s.draft=null;return s.event;}
function spec(e,action,amount){if(action==='skip')return {action,amount:0,fee:0,report:0};if(action==='report')return {action,amount:0,fee:0,report:50};if(!['small','full','custom'].includes(action))throw Error('不支持的行动');const a=amount===undefined?(action==='small'?Math.floor(e.amount/2):e.amount):amount;if(!Number.isInteger(a)||a<1||a>e.amount)throw Error('请输入 1–'+e.amount+' 的整数投入');return {action,amount:a,fee:Math.ceil(a/100),report:0};}
function proposal(s,action,amount,reason=''){if(s.phase!=='event')throw Error('当前无法提交行动');const a=spec(s.event,action,amount);if(a.amount+a.fee+a.report>s.balance)throw Error('可用游戏币不足，可选择观察或仅查报告');return {...a,id:s.event.id,eventVersion:s.event.version,reason:String(reason).slice(0,300),key:s.event.id+'-settle'};}
function replay(e,a){validate(e);const win=rand(e.seed)<e.p/100;const credit=a.amount?Math.floor(a.amount*(win?e.up:e.down)/100):0;return {debit:a.amount+a.fee+a.report,credit,win,delta:credit-a.amount-a.fee-a.report};}
function evidence(s,dimension,value,source='observed_action',phase='before_learning',prompted=false){const key=s.event?.id||'intro';if(s.evidence.some(x=>x.eventId===key&&x.dimension===dimension&&x.value===value))return false;s.evidence.push({id:'ev-'+(s.evidence.length+1),eventId:key,family:s.event?.type||'入场',dimension,value,source,phase,prompted,rule:CONFIG.rule});return true;}
function observe(s,kind,text,prompted=false){const names={risk:'核对风险与退出边界',tech:'核对指标与验证依据',finance:'核对资金占用和备用金',ai:'解释决策理由'};if(!names[kind])return;const fresh=evidence(s,kind,names[kind], 'observed_action',s.lessons.includes(s.event?.concept)?'after_learning':'before_learning',prompted);if(fresh){s.xp+=5;}}
function settle(s,a){const previous=s.ledger.find(x=>x.idempotencyKey===a.key);if(previous)return previous;if(s.phase!=='event'||a.id!==s.event.id||a.eventVersion!==s.event.version)throw Error('行动已过期，请重新确认');const verified=proposal(s,a.action,a.amount||undefined,a.reason);if(verified.amount!==a.amount||verified.fee!==a.fee||verified.report!==a.report)throw Error('草案参数无效');const r=replay(s.event,a),before=s.balance;const entry={ledgerEntryId:'l-'+s.ledger.length,runId:s.id,eventId:a.id,actionId:a.action,idempotencyKey:a.key,balanceBefore:before,balanceAfter:before+r.delta,...r,amount:a.amount,fee:a.fee,report:a.report,ruleVersion:CONFIG.rule,event:JSON.parse(JSON.stringify(s.event)),proposal:{...a}};s.ledger.push(entry);s.balance=entry.balanceAfter;s.xp+=CONFIG.xpPerEvent;if(a.reason.trim().length>=4)observe(s,'ai',a.reason,false);evidence(s,'allocation',Math.round(a.amount/Math.max(1,before)*100)+'% 投入；余款 '+(before-a.amount-a.fee-a.report)+' 币','observed_action','during',false);s.phase='result';s.draft=null;s.version++;return entry;}
function next(s){if(s.phase!=='result')return;s.round++;s.event=null;s.draft=null;s.prompted=[];s.cg='idle';s.phase=s.round>=CONFIG.rounds?'summary':'ready';s.version++;}
function claims(s){return ['risk','tech','finance','ai'].map(id=>{const ev=s.evidence.filter(e=>e.dimension===id);return {id,label:people.find(p=>p.id===id).dimension,events:new Set(ev.map(e=>e.eventId)).size,evidence:ev,status:s.corrections[id]||(ev.length?'candidate':'unknown')};});}
function correct(s,id,status){if(!['confirmed','rejected','roleplay','candidate'].includes(status)||!people.some(p=>p.id===id))throw Error('无效纠正');s.corrections[id]=status;s.profileVersion++;}
function parse(s,text){const t=String(text).trim();if(!t)return {message:'请说说想法，或者直接选择下方方案。'};if(/全仓|借|杠杆|修改余额|充值/.test(t))return {message:'本轮只支持卡面内的无杠杆试验。请选择观察、报告或额度内投入。'};if(/不投|观望|观察|跳过/.test(t))return {action:'skip'};if(/买.*报告|购买.*数据|查报告/.test(t))return {action:'report'};if(/投入|投资|试试|试投/.test(t)){const n=t.match(/[-+]?\d+(?:\.\d+)?/);if(!n)return {message:'请给出具体整数金额，如“投入 500”。我会先出确认单，不会自动扣币。'};return {action:'custom',amount:Number(n[0])};}if(/风险|回撤|止损|退出/.test(t))return {kind:'risk'};if(/指标|数据|样本|回测|验证/.test(t))return {kind:'tech'};if(/费用|资金|仓位|现金|占用|备用/.test(t))return {kind:'finance'};return {message:'我理解你想讨论这个情境。Mock 版支持询问风险、指标、费用，或输入“投入 500”“买报告”“观察”。详细理由也可写在决策说明中。'};}
const API={CONFIG,people,families,rand,fresh,eventFor,validate,draw,spec,proposal,replay,settle,next,observe,evidence,claims,correct,parse};if(typeof module!=='undefined')module.exports=API;else root.Game=API;
})(typeof window==='undefined'?globalThis:window);
